column2:
let Spin = system(
  var p in {idle, busy}
  var q in {wait, crit}
  init p = idle ∧ q = wait
  action pwork when p = idle do p := busy
  action prest when p = busy do p := idle
  action qenter when q = wait do q := crit
)

let Spin2 = system(
  var p in {idle, busy}
  var q in {wait, crit}
  init p = idle ∧ q = wait
  action pwork when p = idle do p := busy
  action prest when p = busy do p := idle
  fair action qenter when q = wait do q := crit
)

let W = system(
  var p in {idle, crit}
  var q in {wait, crit}
  var lock in bool
  init p = idle ∧ q = wait ∧ lock = false
  action penter when p = idle ∧ lock = false do lock := true, p := crit
  action pexit when p = crit do p := idle, lock := false
  fair action qenter when q = wait ∧ lock = false do lock := true, q := crit
)

let S = system(
  var p in {idle, crit}
  var q in {wait, crit}
  var lock in bool
  init p = idle ∧ q = wait ∧ lock = false
  action penter when p = idle ∧ lock = false do lock := true, p := crit
  action pexit when p = crit do p := idle, lock := false
  strong fair action qenter when q = wait ∧ lock = false do lock := true, q := crit
)

let Peterson = system(
  var p in {idle, flag, wait, crit}
  var q in {idle, flag, wait, crit}
  var fp in bool
  var fq in bool
  var turn in {P, Q}
  init p = idle ∧ q = idle ∧ fp = false ∧ fq = false ∧ turn = P
  fair action pflag when p = idle do fp := true, p := flag
  fair action pyield when p = flag do turn := Q, p := wait
  fair action penter when p = wait ∧ (fq = false ∨ turn = P) do p := crit
  fair action pexit when p = crit do fp := false, p := idle
  fair action qflag when q = idle do fq := true, q := flag
  fair action qyield when q = flag do turn := P, q := wait
  fair action qenter when q = wait ∧ (fp = false ∨ turn = Q) do q := crit
  fair action qexit when q = crit do fq := false, q := idle
)

let Forks = system(
  var a in {idle, one, both}
  var b in {idle, one, both}
  var f1 in bool
  var f2 in bool
  init a = idle ∧ b = idle ∧ f1 = false ∧ f2 = false
  action a1 when a = idle ∧ f1 = false do a := one, f1 := true
  action a2 when a = one ∧ f2 = false do a := both, f2 := true
  action arel when a = both do a := idle, f1 := false, f2 := false
  action b1 when b = idle ∧ f2 = false do b := one, f2 := true
  action b2 when b = one ∧ f1 = false do b := both, f1 := true
  action brel when b = both do b := idle, f1 := false, f2 := false
)
